			String sparql = "SELECT (COUNT(*) AS ?total) WHERE { "
					+ ("NAMED".equals(graph) ? "GRAPH <" + GRAPH + "> { " + pattern + " }" : pattern)
					+ " FILTER (?a = ?start) }";
			String gql = ("NAMED".equals(graph) ? "USE GRAPH `" + GRAPH + "` " : "")
					+ "MATCH (a)-[:`" + EDGE + "`]->(middle)-[:`" + EDGE
					+ "`]->(leaf) WHERE a = $start RETURN COUNT(*) AS total";
